      text: "लेने का समय एक अनुमानित मूल्य है। इस प्रकार, दुर्लभ मामले हो सकते हैं, जहां उपज खराब हो जाती है जबकि लेने का समय 0 से बड़ा होता है। ताजा उपज की गुणवत्ता में गिरावट काफी हद तक तापमान पर निर्भर करती है, तापमान डेटा भविष्यवाणी को अधिक सटीक बनाने में मदद करता है। उदाहरण के लिए, समस्या तब उत्पन्न हो सकती है जब ऐप से कोई तापमान सेंसर लिंक न हो, और ऑपरेटर ने कमरे में गलत तापमान सेट कर दिया हो। यदि आपके पास तापमान सेंसर नहीं हैं, तो हम आपको उन्हें अपनी शीतलन इकाइयों में स्थापित करने की सलाह देते हैं। सेटअप के बारे में अधिक जानकारी के लिए कृपया प्रश्न 'मैं कमरे में सेंसर को ऐप से कैसे कनेक्ट करूं' का संदर्भ लें।",
