      role: [ERoles.OPERATOR, ERoles.EMPLOYEE],
      text: "एक पंजीकृत कर्मचारी द्वारा दी गई कूलिंग यूनिट में सेंसर कनेक्शन को सक्षम करने के बाद, 'कूलिंग यूनिट्स'> 'रूम कंडीशंस' पैनल में मैनुअल तापमान इनपुट के लिए बटन ग्रे-आउट हो जाएगा। सेंसर डेटा हर 1 घंटे में प्राप्त किया जाता है, इसलिए यदि सेंसर ठीक से काम कर रहा है तो आपको हर घंटे नए बिंदुओं के साथ तापमान प्लॉट देखना चाहिए।",
