      text: "Pour surveiller la température d'une unité de refroidissement spécifique, cliquez sur le bouton 'Unités de refroidissement' en bas à droite, accédez à 'Conditions de la pièce', et sélectionnez l'unité de refroidissement d'intérêt dans le menu déroulant. Dans ce panneau, vous verrez un graphique avec la température au fil du temps - vous pouvez faire défiler pour voir les données plus anciennes. Si la pièce est équipée de capteurs connectés à l'application, vous pourrez voir la température réelle de la pièce ici. Sinon, le graphique affichera les températures que l'opérateur de la pièce a définies manuellement dans l'application.",
