      text: "Bold ni aarin ni ID ti ohun ipamọ. Aworan ati orukọ ti o wa ni isalẹ ID jẹ aṣoju irugbin na ni ibi ipamọ. Nọmba ti o tẹle awọn aami agbọn sọ fun ọ nọmba awọn apoti inu itutu agbaiye. Nọmba awọn ọjọ ti o wa ni igun apa ọtun loke jẹ awọn ọjọ ibi ipamọ ti o ku ti asọtẹlẹ (= awọn ọjọ titi di akoko lati gbe). 'Wo alaye' ni igun apa ọtun oke jẹ ọna asopọ si wiwo alaye ti nkan ipamọ. Ni isalẹ, orukọ olumulo itutu agbaiye ti han. Nọmba awọn ọjọ ti o wa ni apa ọtun fihan iye ọjọ melo ni wọn ti fipamọ sinu ẹyọ itutu agbaiye. Iye owo naa tọkasi idiyele ojoojumọ fun gbogbo ohun ipamọ, ie idiyele lapapọ fun gbogbo awọn apoti.",
