      text: "Enwere ike iji ngwa a site n'aka ndị ọrụ na ndị na-arụ ọrụ nke ụlọ ọrụ nchekwa oyi yana ndị ọrụ nwere ike ime ka ọ dị jụụ gburugburu ụwa. ngwa ahụ, enwere ọrụ onye ọrụ atọ: (i) Onye ọrụ edebanyere aha: n'ime ndị otu njikwa ụlọ oyi. Onye na-ahụ maka ịtọlite na ijikwa ụlọ ahụ, na-ahụ maka ileghara ọrụ ndị na-arụ ọrụ anya n'ala, na-enweghị anụ ahụ na ebe ahụ. Dịka ọmụmaatụ: onye isi ụlọ ọrụ, CFO, wdg. (ii) Onye ọrụ: onye ọrụ nọ n'anụ ahụ n'ime ụlọ oyi na-ejikwa nbanye ya, ọrụ nlele. Onye a na-akpakọrịta kpọmkwem na ndị ọrụ ụlọ oyi, na-akọkwara onye ọrụ ụlọ ọrụ debanyere aha. (iii) Ndị ọrụ jụrụ oyi: ndị ọrụ ụlọ oyi (nwere ike ịbụ ndị ọrụ ugbo, ndị ahịa, ndị na-ere ahịa, wdg). Ndị ọrụ jụrụ oyi nwere smartphone nwere ike ịbanye na ngwa dị ka ndị ọrụ. Ọ bụrụ na ha enweghị smartphone, ndị na-arụ ọrụ na-arụ ọrụ ndị ọrụ jụrụ oyi n'aha ha.",
