      text: "Lokacin ɗauka shine ƙimar da aka annabta. Don haka, yana yiwuwa mai amfani mai sanyaya zai iya dubawa kuma har yanzu yana sarrafa sayar da kayan ajiya da kyau tare da lokacin ɗauka daidai da kwanaki 0. Duk da haka, ku sani cewa wasu hasara masu inganci ba a iya gani ga idanun mutane, kuma har yanzu yana da kyau a bi alamar da aka ba da lokacin da za ku iya ɗauka. Lokacin ɗaukar tsinkaya daidai ne musamman idan an haɗa app ɗin zuwa na'urori masu auna zafin jiki. Idan ba ku da su a wurin, muna ba ku shawarar shigar da su a cikin sassan sanyaya. Da fatan za a koma ga tambayar 'Yaya zan haɗa na'urori masu auna firikwensin a cikin daki tare da ƙa'idar' don ƙarin bayani game da saitin.",
