      text: 'Sakamakon samun bayanai, an aiwatar da samfurin don wasu kayayyaki kaɗan ne kawai a wasu zaɓaɓɓun jihohi a Indiya da Najeriya. Shafin Farashin Kasuwa kawai yana lissafin kasuwanni, kayayyaki da jahohin da akwai hasashen su.',
