      text: "Kuna iya kewaya zuwa 'Menu' -> 'Management' -> 'Binciken Kuɗi', zaɓi raka'o'in sanyaya da tazarar lokacin sha'awa, kuma zaku ga jimillar kudaden shiga da ke da alaƙa da rajistar daga waɗannan ɗakunan. Hakanan zaka iya tace ta hanyar sanyaya mai amfani, hanyar biyan kuɗi, da amfanin gona. Don ganin taƙaitaccen ƙididdiga na rajistan shiga kowane ɗaki (kamar adadin masu amfani, adadin akwatuna, da sauransu), zaku iya kewaya zuwa 'Menu' -> 'Gudanarwa' -> 'Binciken Amfani'. Hakanan a nan zaku iya tace ta kwanan wata, mai sanyaya mai amfani, da amfanin gona. A ƙarshe, don saka idanu akan jimlar adadin akwatuna, nauyi, da mafi kyawun yanayin zafi don amfanin gona a halin yanzu a cikin ɗakin, zaku iya kewaya zuwa 'Cooling units' -> 'Bayanin Crates'.",
