      text: "Kuna iya karɓar sanarwa iri biyu: na farko, ƙa'idar za ta iya sanar da ku game da gaskiyar cewa wasu akwatunan da kuka adana suna shirin yin ɓarna. Muna ba ku shawara ku tattara akwatunan daga ɗakin da sauri. Wata sanarwar da za ku iya karɓa ita ce tunatar da ku don kammala binciken kasuwar bayan fage. Binciken da ba a cika binciken kasuwa ba yana da alamar ja a cikin shafin 'Tarihi'. Binciken yana da sauri don kammalawa kuma ya tambaye ku game da farashin da aka sayar da kayan amfanin da kuke da shi a ajiya, da kuma ko wani ɓangare na kayan ya lalace bayan an duba. Wannan bayanin yana da matukar amfani ga ƙungiyar Coldtivate don saka idanu akan fa'idar amfani da ɗakunan sanyi idan aka kwatanta da adana kayan amfanin waje.",
