      title: 'كيف يمكنني مراقبة إشغال وحدة التبريد؟',
      role: [ERoles.EMPLOYEE, ERoles.OPERATOR],
      text: "لإدارة إشغال وحدة تبريد معينة، انقر على أيقونة 'وحدات التبريد' في أسفل الشاشة، وانتقل إلى 'المخطط'، واختر الوحدة المطلوبة من القائمة المنسدلة. هنا يمكنك رؤية الإشغال الحالي (في الأعلى) والإشغال المتوقع للأيام الـ 7 القادمة (في الأسفل). تعتمد المعلومات حول الإشغال المستقبلي على عدد الأيام التي يصرح بها كل مستخدم كأيام مخططة في التخزين عند تسجيل الدخول. انتبه إلى أن هذا مجرد تقدير وقد يكون غير دقيق.",
